   [16]={next_id=17, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="浅金色卷发、身着精致礼裙的少女慵懒倚靠在座椅上，白皙的指尖把玩着一枚流光溢彩的宝石，一双剔透的眼眸里盛满不加掩饰的不屑与漠然。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [17]={next_id=18, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在座椅侧边，银白色长发的执事希里静静站着，面无表情。但眼睛紧紧盯着特拉西，封死她所有退路。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [18]={next_id=19, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="拉蒂夫家族的小姐……竟然是你来了。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [19]={next_id=20, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可惜，我们来迟了。那些可怜的居民，在拉蒂夫家族的视野盲区中活的这么艰苦。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [20]={next_id=21, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们这些地下世界的家伙，哪怕只剩几个零星的成员，也还是要掀起几片浪花……真是讨厌。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [21]={next_id=22, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为了一己私欲，不惜将无数无辜之人当成筹码。果然你们这群家伙，还是不要存在在这个世界上才好。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
