   [24]={next_id=25, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你不是在反抗命运，你只是在报复这个世界，把自己承受过的苦难，加倍施加在无辜者身上。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
