   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一旦风暴成型，底层岩层屏障会在短短数秒内被撕碎、崩塌。狂暴的虚粒子乱流会冲出地底，席卷整片弗亚矿区地表。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 1, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
