   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可是地下还有那么多大空洞的居民躺在培养皿里，这么短的时间也仅仅只够将居民送出地表。要想再返回阻止虚粒子风暴，时间根本不够。", msg_color="", msg_size=0, talker="梅鹿特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
