   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我可以留下来。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这里有我的家人，有我建立的余烬，有太多我所珍视的事物。我想要保护他们，哪怕是牺牲我自己，也在所不惜。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个位置，轮不到你们任何人。", msg_color="", msg_size=0, talker="？？？", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就在这一刻，一道略显沙哑且疲惫的男声，从矿道拐角的阴影处缓缓传来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="众人闻声齐齐转头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="阴影之中，浑身沾满尘土与血污的组特缓步走出。他衣衫破损不堪，脸色苍白虚弱，原本桀骜的眼眸此刻褪去所有戾气，只剩下沉甸甸的疲惫与悔过。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="啊！是之前那个帮我们指路的好心人", msg_color="", msg_size=0, talker="梅鹿特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组特走到众人面前，目光坦然，直面所有人的视线，语气平静却无比执拗。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="让我留下来，这是我的……赎罪。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他没有给众人反驳的余地，侧身避开所有人的目光，转头看向身侧的蛰吻，坚硬的眉眼在此刻骤然柔和下来，卸下所有锋芒与倔强。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这位曾经众人口中的“背叛者”，低下了自己的头颅，语气带着小心翼翼的恳求。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻，我只有一个请求。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我妹妹年纪还小，不懂世间险恶。往后我不在了，麻烦你帮我照看她。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="别让她重走我的老路，也别让她……再踏入这片埋葬黑暗与遗憾的废土牢笼。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
